CREATE TABLE public.kb_topics (id text PRIMARY KEY, slug text UNIQUE NOT NULL, name text NOT NULL, description text NOT NULL DEFAULT '', sort integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'published' CHECK(status IN ('draft','published')));
GRANT SELECT ON public.kb_topics TO anon, authenticated; GRANT INSERT, UPDATE, DELETE ON public.kb_topics TO authenticated; GRANT ALL ON public.kb_topics TO service_role;
ALTER TABLE public.kb_topics ENABLE ROW LEVEL SECURITY;
CREATE POLICY topics_read ON public.kb_topics FOR SELECT TO anon, authenticated USING(status='published' OR public.has_permission(auth.uid(),'edit_content'));
CREATE POLICY topics_write ON public.kb_topics FOR ALL TO authenticated USING(public.has_permission(auth.uid(),'edit_content')) WITH CHECK(public.has_permission(auth.uid(),'edit_content'));
CREATE TABLE public.kb_entries (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, topic_id text NOT NULL REFERENCES public.kb_topics(id), question text NOT NULL CHECK(length(question) BETWEEN 2 AND 500), answer text NOT NULL CHECK(length(answer) BETWEEN 1 AND 12000), keywords text[] NOT NULL DEFAULT '{}', link_label text, link_href text CHECK(link_href IS NULL OR (link_href LIKE '/%' AND link_href NOT LIKE '//%' AND link_href !~ '[[:cntrl:]]')), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published')), source text NOT NULL DEFAULT 'team' CHECK(source IN ('site','team','unanswered')), updated_by uuid, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.kb_entries TO anon, authenticated; GRANT INSERT, UPDATE, DELETE ON public.kb_entries TO authenticated; GRANT ALL ON public.kb_entries TO service_role;
ALTER TABLE public.kb_entries ENABLE ROW LEVEL SECURITY;
CREATE POLICY entries_read ON public.kb_entries FOR SELECT TO anon, authenticated USING((status='published' AND EXISTS(SELECT 1 FROM public.kb_topics t WHERE t.id=topic_id AND t.status='published')) OR public.has_permission(auth.uid(),'edit_content'));
CREATE POLICY entries_write ON public.kb_entries FOR ALL TO authenticated USING(public.has_permission(auth.uid(),'edit_content')) WITH CHECK(public.has_permission(auth.uid(),'edit_content'));
CREATE TABLE public.kb_revision (id integer PRIMARY KEY DEFAULT 1 CHECK(id=1), revision bigint NOT NULL DEFAULT 0);
GRANT SELECT ON public.kb_revision TO anon, authenticated; GRANT ALL ON public.kb_revision TO service_role;
ALTER TABLE public.kb_revision ENABLE ROW LEVEL SECURITY;
CREATE POLICY revision_read ON public.kb_revision FOR SELECT TO anon, authenticated USING(id=1);
INSERT INTO public.kb_revision(id) VALUES(1);
CREATE FUNCTION public.bump_kb_revision() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.kb_revision SET revision=revision+1 WHERE id=1; RETURN NULL; END $$;
CREATE TRIGGER entries_revision AFTER INSERT OR UPDATE OR DELETE ON public.kb_entries FOR EACH STATEMENT EXECUTE FUNCTION public.bump_kb_revision();
CREATE TRIGGER topics_revision AFTER INSERT OR UPDATE OR DELETE ON public.kb_topics FOR EACH STATEMENT EXECUTE FUNCTION public.bump_kb_revision();
CREATE FUNCTION public.stamp_kb_editor() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); NEW.updated_by=auth.uid(); RETURN NEW; END $$;
CREATE TRIGGER entries_editor BEFORE INSERT OR UPDATE ON public.kb_entries FOR EACH ROW EXECUTE FUNCTION public.stamp_kb_editor();
CREATE TRIGGER kb_entries_audit AFTER INSERT OR UPDATE OR DELETE ON public.kb_entries FOR EACH ROW EXECUTE FUNCTION public.write_audit();
CREATE TRIGGER kb_topics_audit AFTER INSERT OR UPDATE OR DELETE ON public.kb_topics FOR EACH ROW EXECUTE FUNCTION public.write_audit();
CREATE TABLE public.intake_question_sets(id text PRIMARY KEY, service_key text UNIQUE NOT NULL, name text NOT NULL, questions jsonb NOT NULL DEFAULT '[]' CHECK(jsonb_typeof(questions)='array' AND jsonb_array_length(questions)<=30), sort integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'published' CHECK(status IN ('draft','published')));
GRANT SELECT ON public.intake_question_sets TO anon, authenticated; GRANT INSERT, UPDATE, DELETE ON public.intake_question_sets TO authenticated; GRANT ALL ON public.intake_question_sets TO service_role;
ALTER TABLE public.intake_question_sets ENABLE ROW LEVEL SECURITY;
CREATE POLICY sets_read ON public.intake_question_sets FOR SELECT TO anon, authenticated USING(status='published' OR public.has_permission(auth.uid(),'edit_content'));
CREATE POLICY sets_write ON public.intake_question_sets FOR ALL TO authenticated USING(public.has_permission(auth.uid(),'edit_content')) WITH CHECK(public.has_permission(auth.uid(),'edit_content'));
CREATE TRIGGER intake_sets_audit AFTER INSERT OR UPDATE OR DELETE ON public.intake_question_sets FOR EACH ROW EXECUTE FUNCTION public.write_audit();
CREATE TABLE public.intake_requests(reference text PRIMARY KEY, request_id uuid NOT NULL, request_table text NOT NULL CHECK(request_table IN ('service_requests','electricity_token_requests')), service_key text REFERENCES public.intake_question_sets(service_key), user_id uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.intake_requests TO authenticated; GRANT ALL ON public.intake_requests TO service_role;
ALTER TABLE public.intake_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY intake_requests_read ON public.intake_requests FOR SELECT TO authenticated USING(public.has_permission(auth.uid(),'view_requests'));
CREATE TABLE public.intake_access_tokens(token_hash text PRIMARY KEY, request_reference text NOT NULL REFERENCES public.intake_requests(reference) ON DELETE CASCADE, expires_at timestamptz NOT NULL DEFAULT now()+interval '14 days');
GRANT ALL ON public.intake_access_tokens TO service_role;
ALTER TABLE public.intake_access_tokens ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.intake_answers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_reference text NOT NULL REFERENCES public.intake_requests(reference) ON DELETE CASCADE, question_key text NOT NULL, question_text text NOT NULL, answer text NOT NULL CHECK(length(answer) BETWEEN 1 AND 2000), answered_via text NOT NULL CHECK(answered_via IN ('sophia','web','email')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(request_reference,question_key));
GRANT SELECT ON public.intake_answers TO authenticated; GRANT ALL ON public.intake_answers TO service_role;
ALTER TABLE public.intake_answers ENABLE ROW LEVEL SECURITY;
CREATE POLICY answers_team_read ON public.intake_answers FOR SELECT TO authenticated USING(public.has_permission(auth.uid(),'view_requests'));
CREATE TABLE public.unanswered_questions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), question text NOT NULL CHECK(length(question) BETWEEN 2 AND 2000), page text NOT NULL DEFAULT 'unknown', thread_id uuid NOT NULL REFERENCES public.sophia_threads(id) ON DELETE CASCADE, visitor_email text, status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','answered','dismissed')), answer_entry_id text REFERENCES public.kb_entries(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(thread_id,question));
GRANT SELECT, UPDATE ON public.unanswered_questions TO authenticated; GRANT ALL ON public.unanswered_questions TO service_role;
ALTER TABLE public.unanswered_questions ENABLE ROW LEVEL SECURITY;
CREATE POLICY unanswered_read ON public.unanswered_questions FOR SELECT TO authenticated USING(public.has_permission(auth.uid(),'edit_content'));
CREATE POLICY unanswered_update ON public.unanswered_questions FOR UPDATE TO authenticated USING(public.has_permission(auth.uid(),'edit_content')) WITH CHECK(public.has_permission(auth.uid(),'edit_content'));
CREATE TRIGGER unanswered_audit AFTER UPDATE ON public.unanswered_questions FOR EACH ROW EXECUTE FUNCTION public.write_audit();
CREATE TRIGGER unanswered_alert AFTER INSERT ON public.unanswered_questions FOR EACH ROW EXECUTE FUNCTION public.notify_new_lead();
CREATE FUNCTION public.issue_intake_token(p_reference text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_token text; BEGIN IF NOT EXISTS(SELECT 1 FROM public.intake_requests WHERE reference=p_reference) THEN RAISE EXCEPTION 'Request not found'; END IF; v_token=encode(extensions.gen_random_bytes(32),'hex'); INSERT INTO public.intake_access_tokens(token_hash,request_reference) VALUES(encode(extensions.digest(v_token,'sha256'),'hex'),p_reference); RETURN v_token; END $$;
REVOKE ALL ON FUNCTION public.issue_intake_token(text) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.issue_intake_token(text) TO service_role;
CREATE FUNCTION public.get_intake_form(p_reference text,p_token text,p_user_id uuid,p_bucket text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.intake_requests; q jsonb; BEGIN
IF NOT public.electricity_hit_rate_limit('intake-read:'||left(p_bucket,100),60,600) THEN RAISE EXCEPTION 'Too many requests'; END IF;
SELECT * INTO r FROM public.intake_requests WHERE reference=p_reference;
IF r.reference IS NULL OR NOT ((p_user_id IS NOT NULL AND r.user_id=p_user_id) OR EXISTS(SELECT 1 FROM public.intake_access_tokens WHERE request_reference=p_reference AND token_hash=encode(extensions.digest(coalesce(p_token,''),'sha256'),'hex') AND expires_at>now())) THEN RAISE EXCEPTION 'This link is invalid or expired. Use the link in your email or sign in to your own account.'; END IF;
IF r.request_table='service_requests' AND NOT EXISTS(SELECT 1 FROM public.service_requests WHERE id=r.request_id AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Request not found'; END IF;
SELECT coalesce(jsonb_agg(item),'[]'::jsonb) INTO q FROM public.intake_question_sets s, jsonb_array_elements(s.questions) item WHERE s.service_key=r.service_key AND s.status='published' AND NOT EXISTS(SELECT 1 FROM public.intake_answers a WHERE a.request_reference=p_reference AND a.question_key=item->>'key');
RETURN jsonb_build_object('reference',r.reference,'service_key',r.service_key,'questions',coalesce(q,'[]'::jsonb)); END $$;
REVOKE ALL ON FUNCTION public.get_intake_form(text,text,uuid,text) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.get_intake_form(text,text,uuid,text) TO service_role;
CREATE FUNCTION public.save_intake_answers(p_reference text,p_token text,p_user_id uuid,p_bucket text,p_answers jsonb,p_via text DEFAULT 'web') RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_form jsonb; item jsonb; v_question jsonb; v_count integer=0; v_inserted integer; BEGIN
v_form=public.get_intake_form(p_reference,p_token,p_user_id,p_bucket);
IF NOT public.electricity_hit_rate_limit('intake-save:ip:'||left(p_bucket,100),10,600) OR NOT public.electricity_hit_rate_limit('intake-save:ref:'||p_reference,10,600) THEN RAISE EXCEPTION 'Too many answers. Please try later.'; END IF;
IF p_answers IS NULL OR jsonb_typeof(p_answers)<>'array' OR jsonb_array_length(p_answers)>30 OR p_via NOT IN ('sophia','web','email') THEN RAISE EXCEPTION 'Invalid answers'; END IF;
FOR item IN SELECT value FROM jsonb_array_elements(p_answers) LOOP
IF jsonb_typeof(item->'answer')<>'string' OR length(trim(item->>'answer')) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Answer must contain 1 to 2000 characters'; END IF;
SELECT q INTO v_question FROM public.intake_requests r JOIN public.intake_question_sets s ON s.service_key=r.service_key, jsonb_array_elements(s.questions) q WHERE r.reference=p_reference AND s.status='published' AND q->>'key'=item->>'key';
IF v_question IS NULL THEN RAISE EXCEPTION 'Unknown question'; END IF;
INSERT INTO public.intake_answers(request_reference,question_key,question_text,answer,answered_via) VALUES(p_reference,item->>'key',v_question->>'text',trim(item->>'answer'),p_via) ON CONFLICT(request_reference,question_key) DO NOTHING;
GET DIAGNOSTICS v_inserted=ROW_COUNT; v_count=v_count+v_inserted;
END LOOP; RETURN v_count; END $$;
REVOKE ALL ON FUNCTION public.save_intake_answers(text,text,uuid,text,jsonb,text) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.save_intake_answers(text,text,uuid,text,jsonb,text) TO service_role;
CREATE FUNCTION public.log_sophia_unanswered(p_thread_id uuid,p_visitor_token text,p_question text,p_page text,p_email text,p_bucket text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_id uuid; BEGIN
IF NOT EXISTS(SELECT 1 FROM public.sophia_threads WHERE id=p_thread_id AND visitor_token=p_visitor_token) THEN RAISE EXCEPTION 'Conversation not found'; END IF;
IF length(trim(p_question)) NOT BETWEEN 2 AND 2000 OR length(p_page)>250 OR (coalesce(p_email,'')<>'' AND (length(p_email)>255 OR p_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]{2,}$')) THEN RAISE EXCEPTION 'Invalid question'; END IF;
IF NOT public.electricity_hit_rate_limit('unknown:ip:'||left(p_bucket,100),10,600) OR NOT public.electricity_hit_rate_limit('unknown:thread:'||p_thread_id,10,600) THEN RAISE EXCEPTION 'Too many questions'; END IF;
INSERT INTO public.unanswered_questions(question,page,thread_id,visitor_email) VALUES(trim(p_question),p_page,p_thread_id,nullif(lower(trim(p_email)),'')) ON CONFLICT(thread_id,question) DO UPDATE SET visitor_email=coalesce(unanswered_questions.visitor_email,EXCLUDED.visitor_email) RETURNING id INTO v_id;
RETURN v_id; END $$;
REVOKE ALL ON FUNCTION public.log_sophia_unanswered(uuid,text,text,text,text,text) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.log_sophia_unanswered(uuid,text,text,text,text,text) TO service_role;
CREATE FUNCTION public.answer_publish_unanswered(p_id uuid,p_topic text,p_answer text,p_keywords text[] DEFAULT '{}',p_link_label text DEFAULT NULL,p_link_href text DEFAULT NULL) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.unanswered_questions; v_entry text; BEGIN
IF NOT public.has_permission(auth.uid(),'edit_content') THEN RAISE EXCEPTION 'Forbidden'; END IF;
SELECT * INTO r FROM public.unanswered_questions WHERE id=p_id FOR UPDATE;
IF r.id IS NULL OR r.status<>'new' THEN RAISE EXCEPTION 'Question is not awaiting an answer'; END IF;
INSERT INTO public.kb_entries(topic_id,question,answer,keywords,link_label,link_href,status,source) VALUES(p_topic,r.question,p_answer,p_keywords,p_link_label,p_link_href,'published','unanswered') RETURNING id INTO v_entry;
UPDATE public.unanswered_questions SET status='answered',answer_entry_id=v_entry WHERE id=p_id;
RETURN v_entry; END $$;
REVOKE ALL ON FUNCTION public.answer_publish_unanswered(uuid,text,text,text[],text,text) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.answer_publish_unanswered(uuid,text,text,text[],text,text) TO authenticated;
CREATE FUNCTION public.notify_answered_question() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status='answered' AND OLD.status<>'answered' THEN PERFORM public.notify_new_lead(); END IF; RETURN NEW; END $$;
-- Reuse the existing asynchronous notifier directly for answered rows; handler checks status.
CREATE TRIGGER unanswered_answer_alert AFTER UPDATE ON public.unanswered_questions FOR EACH ROW WHEN (NEW.status='answered' AND OLD.status<>'answered') EXECUTE FUNCTION public.notify_new_lead();
